<template x-for="(term,index) in terms" :key="term.local_key"><article class="mb-4 rounded-2xl border border-gray-200 bg-white dark:border-gray-800 dark:bg-white/[0.03]"><div class="flex items-center justify-between border-b border-gray-100 px-5 py-4 dark:border-gray-800"><h3 class="font-medium">Termine <span x-text="index+1"></span></h3><button type="button" @click="remove(index)" :disabled="terms.length===1" class="text-sm text-error-500 disabled:opacity-40">Elimina termine</button></div><div class="grid gap-4 p-5 sm:grid-cols-2 xl:grid-cols-3"><template x-for="field in ['id','local_key','lock_version']"><input type="hidden" :name="`terms[${index}][${field}]`" :value="term[field]"></template><template x-for="field in ['amount_includes_vat','auto_renew']"><input type="hidden" :name="`terms[${index}][${field}]`" :value="term[field]?1:0"></template><template x-for="[field,label,type] in [['effective_start','Inizio validità','date'],['effective_end','Fine validità','date'],['quantity','Quantità','text'],['unit_price','Prezzo unitario','text'],['entered_amount','Importo inserito','text'],['vat_rate','Aliquota IVA','text']]"><div><label class="label" x-text="label"></label><input :type="type" x-model="term[field]" :name="`terms[${index}][${field}]`" :required="field==='effective_start'||field==='effective_end'||field==='entered_amount'" class="field"><p x-text="errors[`terms.${index}.${field}`]" class="error"></p></div></template><div><label class="label">Ciclo fatturazione</label><select x-model="term.billing_cycle" :name="`terms[${index}][billing_cycle]`" class="field"><option value="monthly">Mensile</option><option value="annual">Annuale</option></select></div><label class="flex h-11 items-center gap-3 self-end rounded-lg border border-gray-300 px-3 text-sm dark:border-gray-700"><input type="checkbox" x-model="term.amount_includes_vat"> Importo IVA inclusa</label><label class="flex h-11 items-center gap-3 self-end rounded-lg border border-gray-300 px-3 text-sm dark:b