<script>function contractForm(terms,vatRate){terms=terms.map(term=>({...term,amount_includes_vat:['1',1,true,'true'].includes(term.amount_includes_vat),auto_renew:['1',1,true,'true'].includes(term.auto_renew)}));return{terms,vatRate,errors:@js($errors->toArray()),add(){this.terms.push({id:null,local_key:'term-new-'+Date.now(),effective_start:'',effective_end:'',billing_cycle:'monthly',quantity:'1.000000',unit_price:'0.000000',entered_amount:'0.000000',amount_includes_vat:false,vat_rate:this.vatRate,auto_renew:false,lock_version:null})},remove(index){if(this.terms.length>1)this.terms.splice(index,1)}}}</script><style>.field{height:2.75rem;width:100%;border-radius:.5rem;border:1px solid #d1d5db;background:transparent;padding:0 .75rem;font-size:.875rem}.textarea{width:100%;border-radius:.5rem;border:1px solid #d1d5db;background:transparent;padding:.5rem .75rem;font-size:.875rem}.label{margin-bottom:.375rem;display:block;font-size:.875rem;font-weight:500}.error{margin-top:.25rem;font-size:.75rem;color:#ef4444}.dark .field,.dark .textarea{border-color:#374151;background:#111827}</style>
